  for(const name of names){if(name.startsWith("."))fail("R20_STORE_STAGING_REMAINS");last=await readCommit(path.join(commits,name),{manifest,staticArtifacts,previousRevision:priorRevision,previousHead:priorHead,name},ops);priorRevision=last.ledger.revision;priorHead=last.ledger.headSha256}
  const partial={};for(const name of ["world-event-ledger.json","behavior-trace.json","godot-trace.json","bridge-report.json","qualification-evidence.json","qualification-abandonment.json",...legacyQualificationNames]){if(await resumeFileExists(path.join(timelineRoot,name),ops))partial[name]=await readText(path.join(timelineRoot,name),name==="qualification-evidence.json"?32*1024*1024:16*1024*1024,ops)}
  if(partial["world-event-ledger.json"]!==undefined&&partial["world-event-ledger.json"]!==last.ledgerText)fail("R20_STORE_PARTIAL_FINALIZATION");if(partial["behavior-trace.json"]!==undefined&&partial["behavior-trace.json"]!==last.traceText)fail("R20_STORE_PARTIAL_FINALIZATION");if(partial["godot-trace.json"]!==undefined)validateR20GodotTraceJson(partial["godot-trace.json"],last.trace.commands,last.trace.entityBindingSha256);if(partial["bridge-report.json"]!==undefined){if(partial["godot-trace.json"]===undefined)fail("R20_STORE_PARTIAL_FINALIZATION");validateR20BridgeReport({manifest,ledgerText:last.ledgerText,traceText:last.traceText,reportText:partial["bridge-report.json"]});}if(["qualification-evidence.json","qualification-abandonment.json",...legacyQualificationNames].some((name)=>partial[name]!==undefined))fail("R20_STORE_PARTIAL_FINALIZATION");
