  const names=(await ops.readdir(stage)).sort(),targetExists=await resumeFileExists(target,ops),expectedCoverageEvidence=await expectedQualificationCoverage(timelineRoot,manifest,ops),behaviorPolicyJson=await readText(path.join(timelineRoot,"behavior-policy.json"),16*1024*1024,ops),entityBindingsJson=await readText(path.join(timelineRoot,"entity-bindings.json"),16*1024*1024,ops),staticArtifacts=validateR20StaticArtifacts(manifest,behaviorPolicyJson,entityBindingsJson),worldEventLedgerJson=await readText(path.join(timelineRoot,"world-event-ledger.json"),16*1024*1024,ops);
