  if(targetExists){await validateStagedEvidence(target);if(names.length!==0)fail("R20_STORE_STAGING_REMAINS");await ops.rmdir(stage);return true}
  if(names.length===0){await ops.rmdir(stage);return false}if(names.join("\0")!=="qualification-evidence.json")fail("R20_STORE_STAGING_REMAINS");
