export async function resumeR20EmptyTimelineStore(request,ops=services){const recovery=request?.recovery;if(!recovery||recovery.status!=="empty-timeline"||typeof recovery.authorityManifestJson!=="string"||typeof request?.behaviorPolicyJson!=="string"||typeof request?.entityBindingJson!=="string"||recovery.behaviorPolicyJson!==request.behaviorPolicyJson||recovery.entityBindingJson!==request.entityBindingJson||request.writerLease===undefined)fail("R20_STORE_RECOVERY_IDENTITY_MISMATCH");const root=directTemp(request.npcRunRoot,request.temporaryRoot,"-npc"),manifestId=digest(Buffer.from(recovery.authorityManifestJson)).slice(7),timelineRoot=path.join(root,"timelines",manifestId);persistentWriterLease(request.writerLease,root,ops);if(manifestId!==recovery.manifestId||timelineRoot!==recovery.timelineRoot)fail("R20_STORE_RECOVERY_IDENTITY_MISMATCH");return createR20TimelineStore({npcRunRoot:request.npcRunRoot,temporaryRoot:request.temporaryRoot,authorityManifestJson:recovery.authorityManifestJson,behaviorPolicyJson:request.behaviorPolicyJson,entityBindingJson:request.entityBindingJson,writerLease:request.writerLease},ops)}

